import csv
import json
import os
from collections import defaultdict

with open('dataset/sample_output.csv', encoding='utf-8') as f:
    outs = list(csv.DictReader(f))

with open('dataset/sample_deletion_requests.csv', encoding='utf-8') as f:
    reqs = list(csv.DictReader(f))

req_map = {r['case_id']: r for r in reqs}

# Pre-load all files into memory or map them
print("Tracking resource IDs from sample output...")
all_resources = {}
for o in outs:
    cid = o['case_id']
    steps = json.loads(o['steps_json'])
    for s in steps:
        res = s['resource_id']
        all_resources[res] = (cid, s['system_id'], s['operation'], s['evidence_id'])

print(f"Total distinct resources in sample output: {len(all_resources)}")

# Search for where each resource appears
res_locations = defaultdict(list)
for root, dirs, files in os.walk('dataset'):
    for f in files:
        if f in ['sample_output.csv', 'output.csv']:
            continue
        p = os.path.join(root, f)
        try:
            with open(p, 'r', encoding='utf-8', errors='ignore') as fp:
                content = fp.read()
                for res in all_resources:
                    if res in content:
                        res_locations[res].append((f, p))
        except Exception:
            pass

print("=== Resource Locations ===")
for res, (cid, sys_id, op, ev_id) in sorted(all_resources.items(), key=lambda x: x[1][0]):
    locs = [f for f, p in res_locations[res]]
    print(f"{cid} | {sys_id:<20} | {res:<20} | ev: {ev_id:<12} | found in: {locs}")

