                elif sys_id == "support_platform":
                    if ev.get("requester_email") is None and ev.get("requester_name") is None:
                        obs = "REDACTED"
                elif sys_id == "security_service":
                    obs = "PRESENT"

                # Canonical system states
                if sys_id == "integration_service" or "data_flow" in res_id:
                    if obs == "PRESENT":
                        obs = "ACTIVE"
