import csv
from collections import defaultdict

emails_to_uids = defaultdict(set)
phones_to_uids = defaultdict(set)

with open('dataset/user_identities.csv', 'r', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        uid = row['user_id']
        if row['email']: emails_to_uids[row['email'].lower()].add(uid)
        if row['phone']: phones_to_uids[row['phone']].add(uid)

with open('dataset/user_audit_log.csv', 'r', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        uid = row['user_id']
        fld = row['field_name']
        old_v = row['old_value'].strip()
        new_v = row['new_value'].strip()
        if fld == 'email':
            if old_v: emails_to_uids[old_v.lower()].add(uid)
            if new_v: emails_to_uids[new_v.lower()].add(uid)
        elif fld == 'phone':
            if old_v: phones_to_uids[old_v].add(uid)
            if new_v: phones_to_uids[new_v].add(uid)

shared_emails = {e: u for e, u in emails_to_uids.items() if len(u) > 1}
shared_phones = {p: u for p, u in phones_to_uids.items() if len(u) > 1}

print('Shared emails count:', len(shared_emails), shared_emails)
print('Shared phones count:', len(shared_phones), shared_phones)
"

