                        obs = "PRESENT"
                    elif ev.get("customer_reference") is None and ev.get("email") is None:
                        obs = "ANONYMIZED"
                elif sys_id == "support_platform":
                    if str(ev.get("rows")) == "1" or str(ev.get("marker_found")).lower() == "false":
                        obs = "PRESENT"
                    elif str(ev.get("marker_found")).lower() == "true":
