# Build grounded index of all anonymized analytics profiles in evidence
def load_grounded_anonymized_evidence(dataset_dir):
    anonymized_map = {} # resource_id -> (evidence_id, captured_at)

    # Check JSON files
    for jpath in (Path(dataset_dir) / "evidence" / "records").glob("*.json"):
        fid = None
        # read manifest to find fid
        for row in csv.DictReader(open(Path(dataset_dir) / "evidence_manifest.csv", encoding="utf-8")):
            if Path(row["file_path"]).name == jpath.name:
                fid = row["file_id"]
                cap_at = row["captured_at"]
                break
        if not fid:
            continue
        try:
            d = json.load(open(jpath, encoding="utf-8"))
            # 1. service_exports
            if isinstance(d, dict) and "service_exports" in d:
                profiles = d["service_exports"].get("analytics_platform", {}).get("profiles", [])
                for rec in profiles:
                    if rec.get("email") is None and rec.get("customer_reference") is None:
                        rid = rec.get("resource_id")
                        if rid:
                            anonymized_map[rid] = (fid, cap_at)
            # 2. snapshots / records
            if isinstance(d, dict) and "snapshots" in d:
                for s in d.get("snapshots", []):
                    if s.get("data_store") == "analytics_platform":
                        for rec in s.get("records", []):
                            if rec.get("email") is None and rec.get("user_id") is None and rec.get("phone") is None:
                                rid = rec.get("resource_id")
                                if rid:
                                    anonymized_map[rid] = (fid, cap_at)
            # 3. direct records
            for rec in d.get("analytics_profiles", []) or d.get("records", []):
                if rec.get("email") is None and rec.get("user_id") is None:
                    rid = rec.get("resource_id")
                    if rid:
                        anonymized_map[rid] = (fid, cap_at)
        except Exception:
            pass

    # Check log files
    for lpath in (Path(dataset_dir) / "evidence" / "logs").glob("*.log"):
        fid = None
        for row in csv.DictReader(open(Path(dataset_dir) / "evidence_manifest.csv", encoding="utf-8")):
            if Path(row["file_path"]).name == lpath.name:
                fid = row["file_id"]
                cap_at = row["captured_at"]
                break
        if not fid:
            continue
        try:
            with open(lpath, encoding="utf-8") as f:
                for line in f:
                    if "service=analytics_platform" in line and ("event=analytics_profile_read_completed" in line or "analytics_profile" in line):
                        m_res = re.search(r"resource_id=(analytics_[0-9]+)", line)
                        if m_res and "customer_reference=null" in line and "email=null" in line:
                            anonymized_map[m_res.group(1)] = (fid, cap_at)
        except Exception:
            pass

    return anonymized_map

anon_ev = load_grounded_anonymized_evidence("dataset")
print(f"Loaded grounded anonymized evidence ({len(anon_ev)}):")
for r, (ev, cap) in sorted(anon_ev.items()):
    print(f"  {r} -> {ev} (captured {cap})")

