import csv, json

def diff_outputs(curr_path, base_path):
    with open(curr_path, 'r', encoding='utf-8') as f:
        curr = {r['case_id']: r for r in csv.DictReader(f)}
    with open(base_path, 'r', encoding='utf-8') as f:
        base = {r['case_id']: r for r in csv.DictReader(f)}

    diffs = {
        'status_changed': [],
        'steps_added': [],
        'steps_removed': [],
        'resource_id_changed': []
    }

    for cid, c_row in curr.items():
        if cid not in base:
            continue
        b_row = base[cid]
        c_status, b_status = c_row['deletion_status'], b_row['deletion_status']
        c_steps = json.loads(c_row['steps_json'])
        b_steps = json.loads(b_row['steps_json'])

        if c_status != b_status:
            diffs['status_changed'].append({
                'case_id': cid,
                'old_status': b_status,
                'new_status': c_status
            })

        # Fingerprint: (phase, operation, system_id, resource_id, state)
        c_fps = [(s['phase'], s['operation'], s['system_id'], s['resource_id'], s['state']) for s in c_steps]
        b_fps = [(s['phase'], s['operation'], s['system_id'], s['resource_id'], s['state']) for s in b_steps]

        # Check added
        c_unmatched = list(c_fps)
        for bf in b_fps:
            if bf in c_unmatched:
                c_unmatched.remove(bf)
        if c_unmatched:
            diffs['steps_added'].append({'case_id': cid, 'added': c_unmatched})

        # Check removed
        b_unmatched = list(b_fps)
        for cf in c_fps:
            if cf in b_unmatched:
                b_unmatched.remove(cf)
        if b_unmatched:
            diffs['steps_removed'].append({'case_id': cid, 'removed': b_unmatched})

        # Check resource_id changed
        # Same (phase, operation, system_id), different resource_id
        for cs in c_steps:
            for bs in b_steps:
                if cs['phase'] == bs['phase'] and cs['operation'] == bs['operation'] and cs['system_id'] == bs['system_id']:
                    if cs['resource_id'] != bs['resource_id']:
                        diffs['resource_id_changed'].append({
                            'case_id': cid,
                            'system_id': cs['system_id'],
                            'old_resource_id': bs['resource_id'],
                            'new_resource_id': cs['resource_id']
                        })
                        break

    return diffs

d = diff_outputs('output.csv', 'backup/baseline_pre_prompt5/output.csv')
print('Status changed:', len(d['status_changed']))
print('Steps added:', len(d['steps_added']))
print('Steps removed:', len(d['steps_removed']))
print('Resource ID changed:', len(d['resource_id_changed']))
"

