import re
from pathlib import Path

log_text = Path('log.txt').read_text(encoding='utf-8')
entries = re.split(r'\n(?=## \[)', log_text)
print('Total entries in log.txt:', len(entries))

errors = []
for idx, entry in enumerate(entries):
    lines = entry.strip().splitlines()
    if not lines: continue
    header = lines[0]

    # Check timestamp format
    m = re.match(r'^## \[([^\]]+)\] (.*)$', header)
    if not m:
        errors.append(f'Entry {idx}: Invalid header format -> {header}')
        continue

    title = m.group(2)
    if 'SESSION START' in title:
        # Check session start fields
        if not any(l.startswith('tool=') for l in lines):
            errors.append(f'Entry {idx} (SESSION START): missing tool=')
        if not any(l.startswith('model=') for l in lines):
            errors.append(f'Entry {idx} (SESSION START): missing model=')
    else:
        # Check per-turn fields
        if 'User Prompt (verbatim, secrets redacted):' not in entry:
            errors.append(f'Entry {idx}: missing User Prompt section ({title[:30]})')
        if 'Agent Response Summary:' not in entry:
            errors.append(f'Entry {idx}: missing Agent Response Summary section ({title[:30]})')
        if 'Actions:' not in entry:
            errors.append(f'Entry {idx}: missing Actions section ({title[:30]})')
        if 'Context:' not in entry:
            errors.append(f'Entry {idx}: missing Context section ({title[:30]})')
        if not re.search(r'tool=[^\s<]+', entry):
            errors.append(f'Entry {idx}: invalid or missing tool= value ({title[:30]})')
        if not re.search(r'model=[^\s<]+', entry):
            errors.append(f'Entry {idx}: invalid or missing model= value ({title[:30]})')
        if '<' in entry and '>' in entry:
            # Check for unfilled placeholders
            placeholders = re.findall(r'<[^>\n]+>', entry)
            # Filter out html tags if any
            placeholders = [p for p in placeholders if not p.startswith('<user_') and not p.startswith('</user_')]
            if placeholders:
                errors.append(f'Entry {idx}: contains unfilled placeholders: {placeholders[:3]}')

print(f'Validation complete: {len(errors)} errors found.')
for e in errors[:10]:
    print(' ', e)
"

