errors = []
for idx, entry in enumerate(entries):
    lines = entry.strip().splitlines()
    if not lines: continue
    header = lines[0]

    m = re.match(r'^## \[([^\]]+)\] (.*)$', header)
    if not m:
        errors.append(f'Entry {idx}: Invalid header -> {header}')
        continue

    title = m.group(2)
    if 'SESSION START' in title:
        # Check required fields
        if not any('tool=' in l for l in lines): errors.append(f'Entry {idx}: missing tool=')
        if not any('model=' in l for l in lines): errors.append(f'Entry {idx}: missing model=')
    else:
        # Check required sections
        if 'User Prompt (verbatim, secrets redacted):' not in entry:
            errors.append(f'Entry {idx}: missing User Prompt')
        if 'Agent Response Summary:' not in entry:
            errors.append(f'Entry {idx}: missing Agent Response Summary')
        if 'Actions:' not in entry:
            errors.append(f'Entry {idx}: missing Actions')
        if 'Context:' not in entry:
            errors.append(f'Entry {idx}: missing Context')
        if not re.search(r'tool=[A-Za-z0-9_-]+', entry):
            errors.append(f'Entry {idx}: missing/invalid tool=')
        if not re.search(r'model=[A-Za-z0-9_\-\.\(\) ]+', entry):
            errors.append(f'Entry {idx}: missing/invalid model=')

